const ELEMENT_PROP_KEYS = new Set(["title","opening","glow","accent","fontFamily","ink","background","scale","delay","grain","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  title: "Introducing remocn",
  opening: "letterbox",
  glow: 1,
  accent: "#3B5BFD",
  fontFamily: "Newsreader",
  scale: 1,
  delay: 0,
  grain: true,
  speed: 1,
};

type SlitRevealElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof SlitRevealBase>;

const SlitRevealInner = forwardRef<
  HTMLDivElement,
  SlitRevealElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
